import { liteClient as algoliasearch } from "algoliasearch/lite";
import {
  Hits,
  InstantSearch,
  SearchBox,
  Highlight,
  RefinementList,
  ToggleRefinement,
  Pagination,
  useNumericMenu,
} from "react-instantsearch";
import "./styles.css";

const searchClient = algoliasearch(
  "PTXSHEFIAL",
  "ecd4eb110c70a6b23a57780303cb485d"
);

function NumericMenu({ attribute, items }) {
  const { items: menuItems, refine } = useNumericMenu({ attribute, items });

  return (
    <ul>
      {menuItems.map((item) => (
        <li key={item.value}>
          <label>
            <input
              type="radio"
              name={attribute}
              checked={item.isRefined}
              onChange={() => refine(item.value)}
            />
            <span>{item.label}</span>
          </label>
        </li>
      ))}
    </ul>
  );
}

function Hit({ hit }) {
  return (
    <article>
      <img src={hit.image} alt={hit.name} />
      <p>{hit.categories[0]}</p>
      <h1>
        <Highlight attribute="name" hit={hit} />
      </h1>
      <p>{hit.description}</p>
      <p>${hit.price}</p>
    </article>
  );
}

export default function App() {
  return (
    <div id="container">
      <InstantSearch searchClient={searchClient} indexName="products-index" insights={true}
      >
        <div id="filters">
          <SearchBox placeholder="Search" />
          <ToggleRefinement
            attribute="free_shipping"
            label="Free shipping"
            on={true}
            off={false}
          />
          <span className="filter-title">Brands</span>
          <RefinementList attribute="brand" showMore />
          <span className="filter-title">Price</span>
          <NumericMenu
            attribute="price"
            items={[
              { label: "All" },
              { label: "Less than $50", end: 50 },
              { label: "Between $50 - $100", start: 50, end: 100 },
              { label: "More than $100", start: 100 },
            ]}
          />
        </div>
        <div id="results">
          <Hits hitComponent={Hit} />
          <Pagination />
        </div>
      </InstantSearch>
    </div>
  );
}
